/* SERVICES */
struct regulator {int id,enabled,voltage,load;};
struct regulator_bulk_data {const char*supply;struct regulator*consumer;};
struct snd_soc_component {struct device*dev;};
static struct regulator regs[4];static int operation,operation_fail,bulk_count,bulk_error;
static int regulator_enable(struct regulator*r){assert(r);if(operation_fail&&++operation==operation_fail)return -EIO;r->enabled++;return 0;}
static int regulator_disable(struct regulator*r){assert(r);if(operation_fail&&++operation==operation_fail)return -EIO;assert(r->enabled>0);r->enabled--;return 0;}
static int regulator_set_voltage(struct regulator*r,int min,int max){assert(r&&min<=max);if(operation_fail&&++operation==operation_fail)return -EIO;r->voltage=min;return 0;}
static int regulator_set_load(struct regulator*r,int load){assert(r);if(operation_fail&&++operation==operation_fail)return -EIO;r->load=load;return 0;}
static int regulator_count_voltages(struct regulator*r){assert(r);return 1;}
static void bulk_release(void*p){(void)p;assert(bulk_count>0);bulk_count--;}
static int devm_regulator_bulk_get(struct device*d,int n,struct regulator_bulk_data*out){assert(n<=4);if(bulk_error)return bulk_error;for(int i=0;i<n;i++)out[i].consumer=&regs[i];bulk_count++;add_resource(d,out,bulk_release);return 0;}
static struct snd_soc_component *component;static int dapm_error,sync_error,sync_count;
static struct snd_soc_component *snd_soc_lookup_component(struct device*d,const char*n){(void)d;(void)n;return component;}
static struct snd_soc_component *snd_soc_component_get_dapm(struct snd_soc_component*c){return c;}
static int snd_soc_dapm_force_enable_pin(struct snd_soc_component*c,const char*n){assert(c&&n);return dapm_error;}
static int snd_soc_dapm_disable_pin(struct snd_soc_component*c,const char*n){assert(c&&n);return dapm_error;}
static int snd_soc_dapm_sync(struct snd_soc_component*c){assert(c);sync_count++;return sync_error;}
/* HEADER */
/* SOURCE */
static struct device_node node;static struct device dev={.of_node=&node};
static struct cdc_regulator cfg[3];static struct regulator_bulk_data supplies[3];
static void setup(void){for(int i=0;i<3;i++){regs[i]=(struct regulator){.id=i};cfg[i]=(struct cdc_regulator){.name=i==0?"a":i==1?"b":"c",.min_uV=100,.max_uV=200,.optimum_uA=50};supplies[i]=(struct regulator_bulk_data){.supply=cfg[i].name,.consumer=&regs[i]};}operation=operation_fail=fail_step=step=bulk_error=0;}
static unsigned votes(void){setup();cfg[0].ondemand=true;operation_fail=1;assert(msm_cdc_enable_ondemand_supply(&dev,supplies,cfg,3,"a")==-EIO&&!cfg[0].vote&&!regs[0].enabled);operation_fail=0;assert(!msm_cdc_enable_ondemand_supply(&dev,supplies,cfg,3,"a")&&cfg[0].vote&&regs[0].enabled==1);operation=0;operation_fail=1;assert(msm_cdc_disable_ondemand_supply(&dev,supplies,cfg,3,"a")==-EIO&&cfg[0].vote&&regs[0].enabled==1);operation_fail=0;assert(!msm_cdc_disable_ondemand_supply(&dev,supplies,cfg,3,"a")&&!cfg[0].vote&&!regs[0].enabled);assert(msm_cdc_enable_ondemand_supply(&dev,supplies,cfg,3,"missing")==-EINVAL);return 5;}
static unsigned errors(void){setup();operation_fail=1;assert(msm_cdc_set_supply_min_voltage(&dev,supplies,cfg,3,"a",110,true)==-EIO);assert(msm_cdc_set_supply_min_voltage(&dev,supplies,cfg,3,"missing",110,true)==-EINVAL);operation_fail=0;assert(!msm_cdc_set_supply_min_voltage(&dev,supplies,cfg,3,"a",110,true)&&regs[0].voltage==110);for(int i=0;i<3;i++)cfg[i].lpm_supported=true;operation=0;operation_fail=1;assert(msm_cdc_set_supplies_lpm_mode(&dev,supplies,cfg,3,false)==-EIO&&regs[1].load==50&&regs[2].load==50);operation_fail=0;assert(!msm_cdc_enable_static_supplies(&dev,supplies,cfg,3));operation=0;operation_fail=1;assert(msm_cdc_disable_static_supplies(&dev,supplies,cfg,3)==-EIO&&cfg[0].vote&&!cfg[1].vote&&!cfg[2].vote);operation_fail=0;assert(!regulator_disable(&regs[0]));return 5;}
static unsigned rollback(void){for(int n=1;n<=3;n++){setup();operation_fail=n;assert(msm_cdc_enable_static_supplies(&dev,supplies,cfg,3)==-EIO);for(int i=0;i<3;i++)assert(!cfg[i].vote&&!regs[i].enabled);}return 3;}
static unsigned initialize(void){for(int n=1;n<=6;n++){setup();struct regulator_bulk_data*out=(void*)1;operation_fail=n;assert(msm_cdc_init_supplies_v2(&dev,&out,cfg,3,false)==-EIO&&!out&&!bulk_count&&!live&&!dev.nr);for(int i=0;i<3;i++)assert(!regs[i].voltage&&!regs[i].load&&!cfg[i].regulator);}for(int n=1;n<=2;n++){setup();fail_step=n;struct regulator_bulk_data*out=(void*)1;assert(msm_cdc_init_supplies(&dev,&out,cfg,3)==-ENOMEM&&!out&&!dev.nr&&!live);}setup();struct regulator_bulk_data*out=(void*)1;bulk_error=-EPROBE_DEFER;assert(msm_cdc_init_supplies(&dev,&out,cfg,3)==-EPROBE_DEFER&&!out&&!dev.nr&&!live);setup();cfg[1].ondemand=true;assert(!msm_cdc_init_supplies_v2(&dev,&out,cfg,3,true)&&out&&bulk_count==1);assert(regs[0].voltage==100&&!regs[1].voltage&&regs[2].load==50);clean(&dev);assert(!bulk_count);return 10;}
static unsigned parse(void){setup();struct cdc_regulator c={0};prop(&node,"a-supply",1,0);assert(msm_cdc_dt_parse_vreg_info(&dev,&c,"a",false)==-EINVAL&&!node.refs);prop(&node,"qcom,a-voltage",2,100);assert(msm_cdc_dt_parse_vreg_info(&dev,&c,"a",false)==-EINVAL&&!node.refs);prop(&node,"qcom,a-current",1,50);assert(!msm_cdc_dt_parse_vreg_info(&dev,&c,"a",false)&&!node.refs&&c.optimum_uA==50);return 3;}
static unsigned dapm(void){struct platform_device pdev={.dev.of_node=&node};found=&pdev;struct cdc_wcd_supply c={0};assert(msm_cdc_init_wcd_supply(&node,"x",&c)==-EPROBE_DEFER&&!pdev.dev.refs&&!c.dev);struct snd_soc_component cmp={.dev=&pdev.dev};component=&cmp;assert(!msm_cdc_init_wcd_supply(&node,"x",&c)&&pdev.dev.refs==1);assert(msm_cdc_enable_wcd_supply(NULL,true)==-EINVAL);dapm_error=-EIO;assert(msm_cdc_enable_wcd_supply(&c,true)==-EIO&&!sync_count);dapm_error=0;sync_error=-EBUSY;assert(msm_cdc_enable_wcd_supply(&c,false)==-EBUSY&&sync_count==1);put_device(c.dev);assert(!pdev.dev.refs);return 5;}
int main(int argc,char**argv){assert(argc==2);unsigned n;if(!strcmp(argv[1],"votes"))n=votes();else if(!strcmp(argv[1],"errors"))n=errors();else if(!strcmp(argv[1],"rollback"))n=rollback();else if(!strcmp(argv[1],"initialize"))n=initialize();else if(!strcmp(argv[1],"parse"))n=parse();else if(!strcmp(argv[1],"dapm"))n=dapm();else abort();printf("{\"supply_%s\":%u}\n",argv[1],n);}
